-- Run ONLY in a fresh, disposable CI database. Never against a Supabase project.
create role anon;
create role authenticated;
create role service_role bypassrls;
create schema auth;
create schema storage;
create schema vault;
create schema extensions;
create schema ccx_internal;
create extension pgcrypto with schema extensions;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth,storage,extensions to service_role,authenticated,anon;
create table auth.users(id uuid primary key);
create table public.account_security(user_id uuid primary key references auth.users,admin boolean default false,banned boolean default false,suspended boolean default false);
create table public.member_profiles(id uuid primary key references auth.users,real_name text,display_name text);
create table public.age_verification_requests(id uuid primary key,user_id uuid references auth.users,status text,provider text,provider_session_id text,verification_method text,evidence_reference text,id_document_path text,selfie_document_path text,verified_at timestamptz,expires_at timestamptz);
create table public.member_admissions(id uuid primary key default gen_random_uuid(),user_id uuid unique references auth.users,source text,verification_id uuid);
create table public.ccx_age_provider_sessions(user_id uuid,provider_session_id text,provider text,mode text,policy_version text);
create function ccx_internal.record_age_admission() returns trigger language plpgsql security definer set search_path='' as $$ begin if NEW.status='approved' and (NEW.expires_at is null or NEW.expires_at>now()) then insert into public.member_admissions(user_id,source,verification_id) values(NEW.user_id,'age_verification',NEW.id) on conflict(user_id) do nothing; end if;return NEW;end $$;
create trigger record_age_admission after insert or update of status on public.age_verification_requests for each row execute function ccx_internal.record_age_admission();
create function ccx_internal.require_yoti_new_approval() returns trigger language plpgsql as $$ begin return NEW;end $$;
create trigger ccx_yoti_approval_only before insert or update of status on public.age_verification_requests for each row execute function ccx_internal.require_yoti_new_approval();
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text);
alter table storage.objects enable row level security;
grant select,insert,update,delete on storage.objects to authenticated,anon;
create policy fixture_broad_access on storage.objects for all to authenticated,anon using(true) with check(true);
create function vault.create_secret(secret text,name text,description text) returns uuid language sql as $$ select gen_random_uuid() $$;
grant select on public.account_security,public.member_admissions,public.ccx_age_provider_sessions to service_role;
grant select,update on public.member_profiles to service_role;
grant select,insert,update on public.age_verification_requests to service_role;
insert into auth.users values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222'),('33333333-3333-4333-8333-333333333333');
insert into public.account_security(user_id) select id from auth.users;
insert into public.member_profiles select id,'Synthetic Claim','Public Stage Name' from auth.users;
